async def get_event(
    self,
    request: Request,
    provider_key: str,
    integration_key: str,
    event_key: str,
) -> TriggerCatalogEventResponse:
    has_permission = await check_action_access(
        user_uid=request.state.user_id,
        project_id=request.state.project_id,
        permission=Permission.VIEW_TRIGGERS,
    )
    if not has_permission:
        raise FORBIDDEN_EXCEPTION

    cache_key = {
        "provider_key": provider_key,
        "integration_key": integration_key,
        "event_key": event_key,
    }
    cached = await get_cache(
        project_id=None,
        namespace="triggers:catalog:event",
        key=cache_key,
        model=TriggerCatalogEventResponse,
    )
    if cached:
        return cached

    event = await self.triggers_service.get_event(
        provider_key=provider_key,
        integration_key=integration_key,
        event_key=event_key,
    )
    if not event:
        return JSONResponse(
            status_code=404,
            content={"detail": "Event not found"},
        )

    response = TriggerCatalogEventResponse(
        count=1,
        event=event,
    )

    await set_cache(
        project_id=None,
        namespace="triggers:catalog:event",
        key=cache_key,
        value=response,
        ttl=5 * 60,
    )

    return response

