async def ingest_composio_event(
    self,
    request: Request,
) -> Any:
    """Receive a Composio provider event; verify, demux, ack-fast, enqueue.

    Public (no Agenta auth) — mirrors the Stripe events receiver. Scope and
    attribution are recovered downstream from the resolved subscription row.
    """
    body = await request.body()

    if not await self.triggers_service.verify_signature(
        body=body, headers=request.headers
    ):
        return JSONResponse(
            status_code=status.HTTP_401_UNAUTHORIZED,
            content={"status": "error", "detail": "Signature verification failed"},
        )

    try:
        envelope = loads(body) if body else {}
    except JSONDecodeError:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="Invalid payload",
        )

    event = normalize_webhook_event(envelope)

    if event is None:
        log.warning(
            "[TRIGGERS] composio event not routable type=%r",
            str(envelope.get("type"))[:64],
        )
        # Accept (no-op) so the provider does not retry.
        return TriggerEventAck(
            status="accepted", detail="No trigger_id/id to route"
        )

    if self.dispatch_task is not None:
        try:
            await asyncio.wait_for(
                self.dispatch_task.kiq(
                    trigger_id=str(event["metadata"]["trigger_id"]),
                    event_id=str(event["metadata"]["id"]),
                    event=event,
                ),
                timeout=_ENQUEUE_TIMEOUT_SECONDS,
            )
        except Exception as e:
            log.error("Failed to enqueue trigger event: %s", e)
            raise HTTPException(
                status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
                detail="Failed to enqueue trigger event",
            ) from e

    return TriggerEventAck(status="accepted")

def resolve_json_path(expr: str, data: dict) -> object:
    json_path, _ = _load_jsonpath()
    if json_path is None:
        raise ImportError("python-jsonpath is required for json-path ($...)")

    if not (expr == "$" or expr.startswith("$.") or expr.startswith("$[")):
        raise ValueError(
            f"Invalid json-path expression {expr!r}. "
            "Must start with '$', '$.' or '$[' (no implicit normalization)."
        )

    results = json_path.findall(expr, data)
    if not results:
        raise KeyError(f"JSONPath {expr!r} matched no values")
    return results[0] if len(results) == 1 else results


def resolve_json_pointer(expr: str, data: Dict[str, Any]) -> Any:
    """Resolve a JSON Pointer; raises KeyError if the pointer does not resolve."""
    _, json_pointer = _load_jsonpath()
    if json_pointer is None:
        raise ImportError("python-jsonpath is required for json-pointer (/...)")
    try:
        return json_pointer(expr).resolve(data)
    except Exception as e:
        # python-jsonpath raises its own JSONPointerResolutionError family on
        # absence; normalize to KeyError so callers can rely on one contract.
        raise KeyError(f"JSON Pointer {expr!r} did not resolve: {e}") from e


def resolve_any(expr: str, data: Dict[str, Any]) -> Any:
    """Dispatch to the right resolver based on detected scheme."""
    scheme = detect_scheme(expr)
    if scheme == "json-path":
        return resolve_json_path(expr, data)
    if scheme == "json-pointer":
        return resolve_json_pointer(expr, data)
    return resolve_dot_notation(expr, data)


def resolve_json_selector(value: Any, data: Dict[str, Any]) -> Any:
    """Resolve a value that may be a JSON Path or JSON Pointer expression.

    - Strings starting with ``$`` are resolved as JSON Path against *data*.
    - Strings starting with ``/`` are resolved as JSON Pointer against *data*.
    - Everything else (plain strings, numbers, dicts, ...) is returned as-is.

    On resolution failure (missing library, invalid syntax, missing path, etc.),
    this helper returns ``None`` instead of raising, as expected by webhook
    callers and design spec.
    """
    if isinstance(value, str):
        try:
            if value.startswith("$"):
                return resolve_json_path(value, data)
            if value.startswith("/"):
                return resolve_json_pointer(value, data)
        except Exception as exc:
            log.debug("Failed to resolve JSON selector %r: %s", value, exc)
            return None
    return value


def resolve_target_fields(
    template: Any,
    context: Dict[str, Any],
    *,
    _depth: int = 0,
) -> Any:
    """Resolve a template into a target by resolving its selector leaves.

    Walks ``template`` (arbitrary JSON); each leaf is passed through
    ``resolve_json_selector`` against *context* (``$``/``/`` selectors resolved,
    everything else returned literally). Null-on-miss, depth-capped at
    ``MAX_RESOLVE_DEPTH``.
    """
    if _depth > MAX_RESOLVE_DEPTH:
        return None
    if isinstance(template, dict):
        return {
            k: resolve_target_fields(v, context, _depth=_depth + 1)
            for k, v in template.items()
        }
    if isinstance(template, list):
        return [
            resolve_target_fields(item, context, _depth=_depth + 1) for item in template
        ]
    try:
        return resolve_json_selector(template, context)
    except Exception:
        return None

